from pathlib import Path
rows=[]
for line in Path('/app/graphene.dat').read_text().splitlines():
    a,b=line.split('\t'); rows.append((float(a.replace(',','.')),float(b.replace(',','.'))))
# summarize equal x windows
for lo,hi in [(1600,1800),(1800,2200),(2200,2500),(2500,2900),(2900,3300),(3300,4000),(4000,6000),(6000,10000),(10000,16000),(16000,18000),(18000,20000),(20000,30000),(30000,48000)]:
 s=[r for r in rows if lo<=r[0]<hi]
 if not s: continue
 im=max(range(len(s)),key=lambda i:s[i][1]);
 print(f'{lo:5}-{hi:5}: n={len(s):4} ymin={min(y for x,y in s):9.2f} ymax={s[im][1]:9.2f}@{s[im][0]:10.3f} avg={sum(y for x,y in s)/len(s):9.2f}')
# local extrema after centered moving averages by point count, x under 5000
ys=[y for x,y in rows]
for radius in [2,5,10,20,40]:
 sm=[]
 # prefix sums
 ps=[0]
 for y in ys: ps.append(ps[-1]+y)
 for i in range(len(rows)):
  a=max(0,i-radius); b=min(len(rows),i+radius+1); sm.append((ps[b]-ps[a])/(b-a))
 peaks=[]
 for i in range(1,len(rows)-1):
  if rows[i][0] < 5000 and sm[i]>sm[i-1] and sm[i]>=sm[i+1]: peaks.append((sm[i],rows[i][0],ys[i],i+1))
 print('\nradius',radius,'top local smoothed peaks x<5000')
 for z in sorted(peaks,reverse=True)[:15]: print(' sm=%9.2f x=%9.3f raw=%9.2f line=%d'%z)
# print points near expected windows sampled every ~10 cm-1
for center in [2700,2680,2650,2600,2000,1800,1700]:
 near=min(range(len(rows)),key=lambda i:abs(rows[i][0]-center))
 print('near',center,'line',near+1,'point',rows[near])
